import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import { Button, Menu, Dropdown, Icon, Row, Col, Input, Table } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import UmbrellaReportStyleWrapper from './umbrella.style'
import umbrellaAction from '../../redux/umbrella/actions'
import PermissionChecker from '../../../components/permissionChecker'
import XLSX from 'xlsx'
import downloader from '../../../helpers/downloader'

const { getAgentData } = umbrellaAction
const SEARCH_STORAGE_KEY = 'agent_table_search'

class AgentTable extends PureComponent {
  constructor(props) {
    super(props)
    const savedSearch = localStorage.getItem(SEARCH_STORAGE_KEY) || ''
    this.state = {
      dataSource: [],
      filteredData: [],
      loading: true,
      searchInput: savedSearch
    }
  }

  componentWillReceiveProps(nextProps) {
    const { agentData } = nextProps.agentList
    if (agentData !== undefined && agentData !== 'Error in fetching details') {
      const resData = agentData.map(val => {
        return {
          name: val.name,
          identity_no: val.identityNo,
          address: val.address,
          referral_code: val.agentId,
          email: val.email,
          register_date: val.createdAt.split('T')[0]
        }
      })
      this.setState({
        dataSource: resData,
        filteredData: this.applySearch(resData, this.state.searchInput),
        loading: false
      })
    } else {
      this.setState({
        dataSource: [],
        filteredData: [],
        loading: false
      })
    }
  }

  componentDidMount() {
    this.props.getAgentData()
  }

  applySearch = (data, searchValue) => {
    if (!searchValue) return data
    const searchLower = searchValue.toLowerCase()
    return data.filter(record =>
      Object.values(record).some(val =>
        val && val.toString().toLowerCase().includes(searchLower)
      )
    )
  }

  viewReferralData = (name, referralCode) => {
    this.props.history.push(`/umbrella_report/${referralCode}/${name}`)
  }

  getColumns = () => {
    const { permissions } = this.props
    return [
      {
        title: 'Action',
        key: 'action',
        width: 110,
        render: (text, record) => (
          <PermissionChecker permissionSetter='ops.view_detail_umbrella_page' permissionGetter={permissions}>
            <Icon
              type='eye'
              style={{ color: '#424242', fontSize: '18px', cursor: 'pointer' }}
              onClick={() => this.viewReferralData(record.name, record.referral_code)}
            />
          </PermissionChecker>
        )
      },
      {
        title: 'Name',
        dataIndex: 'name',
        key: 'name',
        sorter: (a, b) => (a.name || '').localeCompare(b.name || '')
      },
      {
        title: 'Personal Identity No',
        dataIndex: 'identity_no',
        key: 'identity_no',
        sorter: (a, b) => (a.identity_no || '').localeCompare(b.identity_no || '')
      },
      {
        title: 'Address',
        dataIndex: 'address',
        key: 'address',
        sorter: (a, b) => (a.address || '').localeCompare(b.address || '')
      },
      {
        title: 'Referral Code',
        dataIndex: 'referral_code',
        key: 'referral_code',
        sorter: (a, b) => (a.referral_code || '').localeCompare(b.referral_code || '')
      },
      {
        title: 'Email',
        dataIndex: 'email',
        key: 'email',
        sorter: (a, b) => (a.email || '').localeCompare(b.email || '')
      },
      {
        title: 'Registered date',
        dataIndex: 'register_date',
        key: 'register_date',
        sorter: (a, b) => (a.register_date || '').localeCompare(b.register_date || '')
      }
    ]
  }

  dateGenerator = () => {
    let today = new Date()
    let dd = today.getDate()
    let mm = today.getMonth() + 1 // January is 0!
    let yyyy = today.getFullYear()
    if (dd < 10) dd = '0' + dd
    if (mm < 10) mm = '0' + mm
    let assignment = today = mm + '-' + dd + '-' + yyyy
    return assignment
  }

  exportToCsv() {
    const { filteredData } = this.state
    const params = {
      fileName: 'agent_data_' + this.dateGenerator()
    }

    // Prepare data for export
    const exportData = filteredData.map(row => ({
      'Name': row.name || '',
      'Personal Identity No': row.identity_no || '',
      'Address': row.address || '',
      'Referral Code': row.referral_code || '',
      'Email': row.email || '',
      'Registered date': row.register_date || ''
    }))

    // Create worksheet and workbook
    const worksheet = XLSX.utils.json_to_sheet(exportData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Agent Data')

    // Convert to base64
    const xlsxContent = XLSX.write(workbook, { bookType: 'xlsx', type: 'base64' })
    downloader(params, xlsxContent)
  }

  onClearFilter = () => {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.setState({
      searchInput: '',
      filteredData: this.state.dataSource
    })
  }

  onFilterChange(val) {
    const searchValue = val.target.value
    localStorage.setItem(SEARCH_STORAGE_KEY, searchValue)
    this.setState({
      searchInput: searchValue,
      filteredData: this.applySearch(this.state.dataSource, searchValue)
    })
  }

  render() {
    const { filteredData, searchInput, loading } = this.state
    const { permissions } = this.props
    const menu = (
      <Menu onClick={this.exportToCsv.bind(this)}>
        <Menu.Item key='1'><Icon type='right-circle-o' /> Excel</Menu.Item>
      </Menu>
    )
    return (
      <UmbrellaReportStyleWrapper>
        <LayoutContentWrapper className='referral-table' style={{ height: '90vh' }}>
          <LayoutContent style={{ padding: '6vh' }}>
            <Row gutter={16}>
              <Col className='gutter-row-export-csv' span={24} style={{ display: 'flex', justifyContent: 'space-between' }}>
                <h3>Agent Table</h3>
                <div style={{ display: 'flex' }}>
                  <Button style={{ marginRight: '10px' }} onClick={this.onClearFilter}><Icon type='filter' /> Clear filters</Button>
                  <Input value={searchInput} type='text' id='filter-text-box' placeholder='Search...' onInput={val => this.onFilterChange(val)} style={{ width: '200px', borderRadius: '0px', marginRight: '10px' }} />
                  {
                    (permissions !== undefined && permissions.length > 0 && permissions.indexOf('ops.download_umbrella_report') > -1) ? (
                      <Dropdown overlay={menu}>
                        <Button>
                          Export to <Icon type='down' />
                        </Button>
                      </Dropdown>
                    ) : ''
                  }
                </div>
              </Col>
            </Row>
            <Table
              columns={this.getColumns()}
              dataSource={filteredData}
              rowKey={record => record.referral_code || record.name}
              loading={loading}
              pagination={{
                showSizeChanger: true,
                showQuickJumper: true,
                showTotal: (total, range) => `${range[0]}-${range[1]} of ${total} items`
              }}
              locale={{
                emptyText: 'Data is empty :('
              }}
              scroll={{ x: 'max-content' }}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      </UmbrellaReportStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    agentList: state.Umbrella,
    dataProfile: state.Auth.profile
  }),
  { getAgentData }
)(AgentTable)
