import b64ToBlob from './b64ToBlob'

const downloader = (params, content) => {
  const fileNamePresent = params && params.fileName && params.fileName.length !== 0
  const fileName = fileNamePresent ? params.fileName : 'noWarning.xlsx'
  const blobObject = b64ToBlob(
    content,
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  )
  // Internet Explorer
  if (window.navigator.msSaveOrOpenBlob) {
    window.navigator.msSaveOrOpenBlob(blobObject, fileName)
  } else {
    // Chrome
    const downloadLink = document.createElement('a')
    downloadLink.href = URL.createObjectURL(blobObject)
    downloadLink.download = fileName
    document.body.appendChild(downloadLink)
    downloadLink.click()
    document.body.removeChild(downloadLink)
  }
}

export default downloader
